namespace sv_a35ee6c9168c463d8c19621f89df9676.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that tracks the currently selected warehouse for one user circuit.
/// All components that inject this service and subscribe to OnChange stay synchronized.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "wh-1", Name = "Warehouse A — East" },
        new() { Id = "wh-2", Name = "Warehouse B — West" },
        new() { Id = "wh-3", Name = "Warehouse C — Central" },
    ];

    public WarehouseInfo Current { get; private set; } = AvailableWarehouses[0];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var match = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (match is not null && match.Id != Current.Id)
        {
            Current = match;
            OnChange?.Invoke();
        }
    }
}

namespace sv_a35ee6c9168c463d8c19621f89df9676.Services;

/// <summary>
/// Simulates a database query for low-stock items in a warehouse.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database call with a random count 0–15.
        return Task.FromResult(_random.Next(0, 16));
    }
}

namespace sv_a35ee6c9168c463d8c19621f89df9676.Services;

/// <summary>
/// Scoped service that manages periodic low-stock polling for the current warehouse.
/// Components subscribe to OnAlertCountChanged to receive updates.
/// Polling only runs while at least one subscriber has called StartPolling.
/// </summary>
public class InventoryAlertState : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseState _warehouseState;

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _pollingSubscribers;

    public int LowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertState(InventoryAlertService alertService, WarehouseState warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;

        // When the warehouse changes, immediately refresh the alert count.
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Increment the polling subscriber count and start the timer if not already running.
    /// </summary>
    public async Task StartPollingAsync()
    {
        _pollingSubscribers++;
        if (_pollingSubscribers == 1)
        {
            await RefreshAsync();
            StartTimer();
        }
    }

    /// <summary>
    /// Decrement the polling subscriber count and stop the timer when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _pollingSubscribers = Math.Max(0, _pollingSubscribers - 1);
        if (_pollingSubscribers == 0)
        {
            StopTimer();
        }
    }

    /// <summary>
    /// Fetch the latest alert count and notify all subscribers.
    /// </summary>
    public async Task RefreshAsync()
    {
        LowStockCount = await _alertService.GetLowStockCountAsync(_warehouseState.Current.Id);
        OnAlertCountChanged?.Invoke();
    }

    private void StartTimer()
    {
        StopTimer();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / stop.
        }
    }

    private async void OnWarehouseChanged()
    {
        // Warehouse switched — immediately refresh regardless of timer.
        await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopTimer();
    }
}

