arguments.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@inject sv_a35ee6c9168c463d8c19621f89df9676.Services.WarehouseState WarehouseState
@inject sv_a35ee6c9168c463d8c19621f89df9676.Services.InventoryAlertState AlertState
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-5">@WarehouseState.Current.Name</p>
    </div>
</div>

<div class="card mb-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            @if (AlertState.LowStockCount > 0)
            {
                <span class="badge bg-danger ms-2">@AlertState.LowStockCount items</span>
            }
            else
            {
                <span class="badge bg-success ms-2">All stocked</span>
            }
        </h5>
        <p class="text-muted">Refreshes every 10 seconds while this page is open.</p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertState.OnAlertCountChanged += _alertHandler;

        // Start polling when the dashboard is visible.
        await AlertState.StartPollingAsync();
    }

    public void Dispose()
    {
        // Stop polling when the user leaves the page.
        AlertState.StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertState.OnAlertCountChanged -= _alertHandler;
    }
}

